B.c9U=new A.a("\u0420\u0430\u0437\u043d\u0438\u0446\u0430 \u043c\u0435\u0436\u0434\u0443 \u043e\u0436\u0438\u0434\u0430\u0435\u043c\u043e\u0439 \u0446\u0435\u043d\u043e\u0439 \u0441\u0434\u0435\u043b\u043a\u0438 \u0438 \u0446\u0435\u043d\u043e\u0439, \u043f\u043e \u043a\u043e\u0442\u043e\u0440\u043e\u0439 \u043e\u043d\u0430 \u0440\u0435\u0430\u043b\u044c\u043d\u043e \u0438\u0441\u043f\u043e\u043b\u043d\u0438\u043b\u0430\u0441\u044c.","\u0420\u0456\u0437\u043d\u0438\u0446\u044f \u043c\u0456\u0436 \u043e\u0447\u0456\u043a\u0443\u0432\u0430\u043d\u043e\u044e \u0446\u0456\u043d\u043e\u044e \u0443\u0433\u043e\u0434\u0438 \u0442\u0430 \u0446\u0456\u043d\u043e\u044e, \u0437\u0430 \u044f\u043a\u043e\u044e \u0432\u043e\u043d\u0430 \u0440\u0435\u0430\u043b\u044c\u043d\u043e \u0432\u0438\u043a\u043e\u043d\u0430\u043b\u0430\u0441\u044f.","The difference between the expected trade price and the actual fill price.")
B.cem=new A.a("\u041d\u0430 DEX \u043d\u0435 \u0441\u0442\u0430\u0432\u044c\u0442\u0435 \u0432\u044b\u0441\u043e\u043a\u043e\u0435 \u0434\u043e\u043f\u0443\u0441\u0442\u0438\u043c\u043e\u0435 \u043f\u0440\u043e\u0441\u043a\u0430\u043b\u044c\u0437\u044b\u0432\u0430\u043d\u0438\u0435: \u044d\u0442\u0438\u043c \u043f\u043e\u043b\u044c\u0437\u0443\u044e\u0442\u0441\u044f \u0431\u043e\u0442\u044b (\u0441\u044d\u043d\u0434\u0432\u0438\u0447-\u0430\u0442\u0430\u043a\u0438).","\u041d\u0430 DEX \u043d\u0435 \u0441\u0442\u0430\u0432\u0442\u0435 \u0432\u0438\u0441\u043e\u043a\u0435 \u0434\u043e\u043f\u0443\u0441\u0442\u0438\u043c\u0435 \u043f\u0440\u043e\u0441\u043b\u0438\u0437\u0430\u043d\u043d\u044f: \u0446\u0438\u043c \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u044e\u0442\u044c\u0441\u044f \u0431\u043e\u0442\u0438 (\u0441\u0435\u043d\u0434\u0432\u0456\u0447-\u0430\u0442\u0430\u043a\u0438).","Do not set high slippage tolerance on a DEX, bots exploit it (sandwich attacks).")
B.cwz=new A.ad("slippage",B.bw,B.adg,B.c9U,B.cem)
