B.cnc=new A.a("\u0421\u0442\u043e\u043f-\u043b\u043e\u0441\u0441, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u0441\u0430\u043c \u043f\u043e\u0434\u0442\u044f\u0433\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u0437\u0430 \u0446\u0435\u043d\u043e\u0439 \u043d\u0430 \u0437\u0430\u0434\u0430\u043d\u043d\u043e\u043c \u0440\u0430\u0441\u0441\u0442\u043e\u044f\u043d\u0438\u0438, \u043d\u043e \u043d\u0435 \u043e\u0442\u0445\u043e\u0434\u0438\u0442 \u043d\u0430\u0437\u0430\u0434.","\u0421\u0442\u043e\u043f-\u043b\u043e\u0441, \u044f\u043a\u0438\u0439 \u0441\u0430\u043c \u043f\u0456\u0434\u0442\u044f\u0433\u0443\u0454\u0442\u044c\u0441\u044f \u0437\u0430 \u0446\u0456\u043d\u043e\u044e \u043d\u0430 \u0437\u0430\u0434\u0430\u043d\u0456\u0439 \u0432\u0456\u0434\u0441\u0442\u0430\u043d\u0456, \u0430\u043b\u0435 \u043d\u0435 \u0432\u0456\u0434\u0445\u043e\u0434\u0438\u0442\u044c \u043d\u0430\u0437\u0430\u0434.","A stop-loss that follows price at a set distance but never moves back.")
B.bXp=new A.a("\u041f\u043e\u043c\u043e\u0433\u0430\u0435\u0442 \u0443\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0442\u044c \u043f\u0440\u0438\u0431\u044b\u043b\u044c \u0432 \u0442\u0440\u0435\u043d\u0434\u0435. \u0421\u043b\u0438\u0448\u043a\u043e\u043c \u0431\u043b\u0438\u0437\u043a\u0438\u0439 \u0442\u0440\u0435\u0439\u043b\u0438\u043d\u0433 \u0432\u044b\u0431\u044c\u0435\u0442 \u043d\u0430 \u043e\u0431\u044b\u0447\u043d\u043e\u043c \u043e\u0442\u043a\u0430\u0442\u0435.","\u0414\u043e\u043f\u043e\u043c\u0430\u0433\u0430\u0454 \u0443\u0442\u0440\u0438\u043c\u0443\u0432\u0430\u0442\u0438 \u043f\u0440\u0438\u0431\u0443\u0442\u043e\u043a \u0443 \u0442\u0440\u0435\u043d\u0434\u0456. \u041d\u0430\u0434\u0442\u043e \u0431\u043b\u0438\u0437\u044c\u043a\u0438\u0439 \u0442\u0440\u0435\u0439\u043b\u0456\u043d\u0433 \u0432\u0438\u0431'\u0454 \u043d\u0430 \u0437\u0432\u0438\u0447\u0430\u0439\u043d\u043e\u043c\u0443 \u0432\u0456\u0434\u043a\u0430\u0442\u0456.","It keeps profits in a trend, but a trail that's too tight gets hit by normal pullbacks.")
B.cwR=new A.ad("trailing_stop",B.bw,B.bD8,B.cnc,B.bXp)
